/**
 * Indices over a graph's containment edges.
 *
 * `containment` is a flat list of (summary, descendant) pairs, and it is
 * TRANSITIVE — one entry per descendant, not per child — so its length is
 * O(records x depth). Answering "which nodes does THIS summary contain" by
 * filtering that list costs O(containment) per question, and the planner asks
 * it several times per summary per pass, which made one scheduling pass
 * quadratic in the record count.
 *
 * **Rule for anyone adding a per-summary computation:** ask
 * `graph.descendantsOf`, never `graph.containment`. Iterating the flat list is
 * correct only for work that is proportional to the whole list once — the
 * toposort's containment-edge push is the one legitimate case.
 */

import type { NormalizedTaskID } from "../types";
import type { ContainmentEdge } from "./types";

export interface ContainmentIndices {
  /** summary ID -> its (transitive) descendants that are graph nodes. */
  readonly descendantsOf: ReadonlyMap<NormalizedTaskID, readonly NormalizedTaskID[]>;
  /** descendant ID -> the summaries that contain it. Its length is the node's containment depth. */
  readonly containingSummaries: ReadonlyMap<NormalizedTaskID, readonly NormalizedTaskID[]>;
}

/** Shared empty list, so a summary with no row allocates nothing at the read site. */
export const NO_DESCENDANTS: readonly NormalizedTaskID[] = [];

export function buildContainmentIndices(
  containment: readonly ContainmentEdge[]
): ContainmentIndices {
  const descendantsOf = new Map<NormalizedTaskID, NormalizedTaskID[]>();
  const containingSummaries = new Map<NormalizedTaskID, NormalizedTaskID[]>();
  for (const c of containment) {
    push(descendantsOf, c.summary, c.descendant);
    push(containingSummaries, c.descendant, c.summary);
  }
  return { descendantsOf, containingSummaries };
}

function push(
  map: Map<NormalizedTaskID, NormalizedTaskID[]>,
  key: NormalizedTaskID,
  value: NormalizedTaskID
): void {
  const arr = map.get(key);
  if (arr) arr.push(value);
  else map.set(key, [value]);
}
