import type {
  Conflict,
  LinkID,
  NormalizedLinkID,
  NormalizedTaskID,
  ScheduleReason,
  Snapshot,
  TaskID
} from "./types";
import { getSnapshotLink } from "./snapshot_links";

export function normalizeTaskId(id: TaskID): NormalizedTaskID {
  return String(id);
}

export function normalizeLinkId(id: LinkID): NormalizedLinkID {
  return String(id);
}

export function normalizeTaskIdSet(ids: ReadonlySet<TaskID> | undefined): ReadonlySet<NormalizedTaskID> | undefined {
  if (!ids) return undefined;
  const result = new Set<NormalizedTaskID>();
  for (const id of ids) result.add(normalizeTaskId(id));
  return result;
}

export function taskIdLookupCandidates(id: TaskID): readonly TaskID[] {
  if (typeof id === "number") return [id, String(id)];
  const numeric = Number(id);
  if (!Number.isNaN(numeric) && String(numeric) === id) return [id, numeric];
  return [id];
}

export function rawTaskId(snapshot: Snapshot, id: NormalizedTaskID): TaskID {
  return snapshot.tasks.get(id)?.rawId ?? id;
}

export function rawLinkId(snapshot: Snapshot, id: NormalizedLinkID): LinkID {
  return getSnapshotLink(snapshot, id)?.rawId ?? id;
}

export function toPublicScheduleReason(snapshot: Snapshot, reason: ScheduleReason): ScheduleReason {
  switch (reason.kind) {
    case "asap": {
      const linkId = normalizeLinkId(reason.linkId);
      return {
        kind: "asap",
        linkId: rawLinkId(snapshot, linkId),
        sourceId: publicEndpointId(snapshot, normalizeTaskId(reason.sourceId), linkId, "source")
      };
    }
    case "alap": {
      const linkId = normalizeLinkId(reason.linkId);
      return {
        kind: "alap",
        linkId: rawLinkId(snapshot, linkId),
        targetId: publicEndpointId(snapshot, normalizeTaskId(reason.targetId), linkId, "target")
      };
    }
    case "summary-translation":
      return {
        kind: "summary-translation",
        summaryId: rawTaskId(snapshot, normalizeTaskId(reason.summaryId))
      };
    case "constraint":
    case "preferred":
      return reason;
    default: {
      const _exhaustive: never = reason;
      void _exhaustive;
      return reason;
    }
  }
}

/**
 * Replace an endpoint that names an INTERNAL graph node with the endpoint of the
 * link the reason belongs to — staying in the normalized id space.
 *
 * GS-3596 added internal nodes that stand for a project's shape rather than for
 * a task (`core/graph/project_shape_edges.ts`), and one of them can be the
 * driving edge's source, which the resolver copies into the reason. That id
 * answers to no task, so it must not travel with a `PlanResult`: `plan()` maps
 * every reason through here, which keeps the promise that a plan never names a
 * node that is not a task — `plans` keys, `order` and reasons alike. The link's
 * own endpoint is the real, user-visible cause ("this moved because of link L
 * from project P").
 *
 * Applied at the source rather than per consumer: the adapter hands whole
 * `PlanResult`s to `onAutoScheduleNoConverge`, and any future reader of a plan
 * inherits the guarantee instead of having to remember it.
 */
export function toTaskEndpointReason(snapshot: Snapshot, reason: ScheduleReason): ScheduleReason {
  switch (reason.kind) {
    case "asap": {
      if (snapshot.tasks.has(reason.sourceId as NormalizedTaskID)) return reason;
      const endpoint = linkEndpoint(snapshot, normalizeLinkId(reason.linkId), "source");
      return endpoint === undefined ? reason : { ...reason, sourceId: endpoint };
    }
    case "alap": {
      if (snapshot.tasks.has(reason.targetId as NormalizedTaskID)) return reason;
      const endpoint = linkEndpoint(snapshot, normalizeLinkId(reason.linkId), "target");
      return endpoint === undefined ? reason : { ...reason, targetId: endpoint };
    }
    default:
      // `summary-translation` names a real summary; the rest carry no ids.
      return reason;
  }
}

/** The link's own endpoint, normalized. `undefined` if the link is gone. */
function linkEndpoint(
  snapshot: Snapshot,
  linkId: NormalizedLinkID,
  side: "source" | "target"
): NormalizedTaskID | undefined {
  const link = getSnapshotLink(snapshot, linkId);
  if (!link) return undefined;
  return side === "source" ? link.source : link.target;
}

/**
 * The task id to report for the endpoint that drove a date.
 *
 * Normally the resolved endpoint IS a task and this is `rawTaskId`. The fallback
 * covers an internal endpoint that reached here without passing through
 * `toTaskEndpointReason` — `deriveEventArgs` hands the reason's id straight to
 * `gantt.getTask` for the `onBeforeTaskAutoSchedule` / `onAfterTaskAutoSchedule`
 * argument, so a synthetic id must never get this far.
 */
function publicEndpointId(
  snapshot: Snapshot,
  id: NormalizedTaskID,
  linkId: NormalizedLinkID,
  side: "source" | "target"
): TaskID {
  if (snapshot.tasks.has(id)) return snapshot.tasks.get(id)!.rawId;
  const link = getSnapshotLink(snapshot, linkId);
  if (link) return side === "source" ? link.rawSource : link.rawTarget;
  return id;
}

export function toPublicConflict(snapshot: Snapshot, conflict: Conflict): Conflict {
  switch (conflict.kind) {
    case "constraint-violation":
      return { ...conflict, taskId: rawTaskId(snapshot, normalizeTaskId(conflict.taskId)) };
    case "calendar-non-working":
      return { ...conflict, taskId: rawTaskId(snapshot, normalizeTaskId(conflict.taskId)) };
    case "cycle":
      return {
        ...conflict,
        taskIds: conflict.taskIds.map(id => rawTaskId(snapshot, normalizeTaskId(id))),
        linkIds: conflict.linkIds.map(id => rawLinkId(snapshot, normalizeLinkId(id)))
      };
    case "unscheduled-dependency":
      return {
        ...conflict,
        taskId: rawTaskId(snapshot, normalizeTaskId(conflict.taskId)),
        blockedBy: rawTaskId(snapshot, normalizeTaskId(conflict.blockedBy))
      };
    default: {
      const _exhaustive: never = conflict;
      void _exhaustive;
      return conflict;
    }
  }
}
